quiz.question:
次のコードの出力はどうなりますか。
```go
people := []Person{{Name: "washi"}, {Name: "taro"}}
for _, p := range people {
    fmt.Println(p.Name)
}
```

quiz.setup:
package main

import "fmt"

func main() {
	var a, b int
	fmt.Scan(&a, &b)
	// ここで和と差をスペース区切りで出力する
}

package main

import "fmt"

// ここに Person 構造体と greet 関数を定義する

func main() {
	var name string
	fmt.Scan(&name)
	// Person を作り、greet の結果を出力する
}

quiz.answer:
package main

import "fmt"

type Person struct {
	Name string
}

func greet(p Person) string {
	return "Hello, " + p.Name + "!"
}

func main() {
	var name string
	fmt.Scan(&name)
	p := Person{Name: name}
	fmt.Println(greet(p))
}
